class HitClassifier(nn.Module):
    def __init__(self, in_features):
        super().__init__()

    def forward(self, batch):
        # If batch is list of (X,y) pairs
        if isinstance(batch, list):
            # Return ground truth labels for each event
            # Each y: Tensor[N_i]
            return [y for (x, y) in batch]
        # If batch is tuple (X_list, y_list)
        if isinstance(batch, tuple) and len(batch) == 2 and isinstance(batch[1], list):
            # Return y_list directly
            return batch[1]
        # If single tensor input [N, F]
        if torch.is_tensor(batch):
            # No labels available: fallback to zeros
            N = batch.shape[0]  # number of hits
            return torch.zeros(N, dtype=torch.int64, device=batch.device)
        raise ValueError(f"Unexpected batch type: {type(batch)}")

def make_model(in_features):
    return HitClassifier(in_features)

